css:
/* ==== INTERFACE ====
方向：经典学术专著导读与社会学思想实验。融合 Editorial 杂志排版与典籍印刷质感：米灰纸本基底、深炭黑墨色、暖赭与锈金提示；以衬线大标题与高阶排版节奏呈现韦伯命题的严密性与文献张力。
token --bg：页面底色（暖米羊皮纸色 #F4F1EA）。
token --text：正文主色（深沉墨黑 #1C1A17）。
token --font-sans：界面标签、图例、数据刻度与通识辅助字体（Inter + Noto Sans SC）。
token --font-serif：主标题、核心引语与天职学说阐释的衬线文字栈（Source Serif 4 + Noto Serif SC）。
class .nt-title：普通页主标题，默认衬线（--font-serif），44px / 行高 1.2，墨黑 #1C1A17，字重 600。
class .nt-subtitle：页面副题或论证模块名，无衬线大写略宽字距，14px / 行高 1.4，字重 600，颜色 --muted-dark。
class .nt-display：封面或核心命题强调特大展示字，衬线体，64px–72px / 行高 1.1，字重 700。
class .nt-lead：导读段落或章节提要，20px / 行高 1.6，字重 400，颜色 --text。
class .nt-body：正文解析段落，16px / 行高 1.65，字重 400，颜色 --text。
class .nt-quote：韦伯/富兰克林原著经典引语，带细左边线（2px solid var(--accent-ochre)），左内边距 24px，斜体或衬线 18px / 行高 1.6。
class .nt-caption：图注与文献出处，无衬线 13px / 行高 1.45，颜色 --muted。
class .nt-badge：学派/概念胶囊标签（如“天职观 Beruf”、“世俗禁欲主义”、“因果链辨析”），无衬线 12px，字重 500。
class .nt-rule：经典学术文献排版细横线，高 1px，颜色 var(--border)。
class .nt-card：学术推演与对比白底/纸色轻抬升板块，细描边 1px solid var(--border)，柔和微影，圆角 4px。
variant opening：开篇专属大气构图，舞台带有微细纸质印刷网纹与暖色边际渐晕。
默认：不设 data-variant；无图时呈现细腻暖调米纸色纯净舞台。
==== /INTERFACE ==== */

/* 字体声明：使用已备妥的真实资源 */
@font-face {
  font-family: "NTF-noto-serif-sc";
  src: url("fonts/library/noto-serif-sc/face-0.ttf");
  font-weight: 200 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-source-serif-4";
  src: url("fonts/library/source-serif-4/face-0.ttf");
  font-weight: 200 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-source-serif-4";
  src: url("fonts/library/source-serif-4/face-1.ttf");
  font-weight: 200 900;
  font-style: italic;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-1.ttf");
  font-weight: 100 900;
  font-style: italic;
  font-display: swap;
}

@font-face {
  font-family: "NTF-noto-sans-sc";
  src: url("fonts/library/noto-sans-sc/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

:root {
  /* 配色系统：采选自 grid-to-preview、ThumbHoverSVGFilter、menu-story 与 ContextAwareLogo */
  --bg: #F5F2EB;
  --bg-alt: #ECE7DD;
  --bg-card: #FAF8F5;
  --surface: #FFFFFF;
  --text: #1E1B18;
  --text-pure: #110F0D;
  --muted: #736E65;
  --muted-dark: #4A463F;
  --muted-light: #A39D92;
  --border: #DDD6C8;
  --border-light: #EBE5DA;
  --border-dark: #BDB4A1;

  /* 学术与观念强调色 */
  --accent-ochre: #964F24;      /* 韦伯论题核心：禁欲与资本积累之火（暖赭红） */
  --accent-gold: #C08A3E;       /* 富兰克林箴言、天职信条金 */
  --accent-slate: #3B5360;      /* 制度、理性化与现代官僚秩序（冷灰蓝） */
  --accent-green: #385E48;      /* 生产再投入、持续资本增长 */
  --accent-crimson: #8C2D2B;    /* 预定论焦虑、宗教张力 */
  --focus: #964F24;

  /* 字体栈分配：英前中后，拉丁字符命中精美 serif，汉字承接 noto-serif-sc */
  --font-serif: "NTF-source-serif-4", "NTF-noto-serif-sc", "Source Serif Pro", Georgia, "Songti SC", serif;
  --font-sans: "NTF-inter", "NTF-noto-sans-sc", -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif;
  --font-mono: "NTF-inter", SFMono-Regular, Consolas, monospace;

  /* 逻辑字阶体系 */
  --fs-display: 64px;
  --fs-h1: 44px;
  --fs-h2: 28px;
  --fs-h3: 20px;
  --fs-lead: 20px;
  --fs-body: 16px;
  --fs-sec: 14px;
  --fs-label: 13px;
  --fs-tick: 11px;

  /* 间距与韵律 */
  --lh-tight: 1.15;
  --lh-heading: 1.25;
  --lh-body: 1.65;
  --lh-relaxed: 1.8;

  /* 投影与微质感 */
  --shadow-sm: 0 1px 3px rgba(30, 27, 24, 0.05);
  --shadow-md: 0 4px 16px rgba(30, 27, 24, 0.07);
  --shadow-book: 0 10px 30px rgba(30, 27, 24, 0.09), 0 1px 3px rgba(30, 27, 24, 0.04);
}

/* 1600x900 固定舞台基础 */
#stage {
  box-sizing: border-box;
  background-color: var(--bg);
  background-image: 
    radial-gradient(ellipse at 85% 15%, rgba(192, 138, 62, 0.06) 0%, transparent 60%),
    radial-gradient(ellipse at 15% 85%, rgba(150, 79, 36, 0.05) 0%, transparent 50%),
    linear-gradient(to right, rgba(221, 214, 200, 0.2) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(221, 214, 200, 0.2) 1px, transparent 1px);
  background-size: 100% 100%, 100% 100%, 80px 80px, 80px 80px;
  background-position: center center;
  color: var(--text);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* 变体：开篇封面 */
html[data-variant="opening"] #stage {
  background-color: #EFEBE1;
  background-image:
    radial-gradient(circle at 50% 40%, rgba(255, 255, 255, 0.4) 0%, transparent 70%),
    radial-gradient(ellipse at 80% 90%, rgba(150, 79, 36, 0.08) 0%, transparent 50%),
    linear-gradient(180deg, rgba(236, 231, 221, 0.7) 0%, rgba(245, 242, 235, 1) 100%);
  background-size: 100% 100%;
}

/* 变体：深色沉思/铁笼隐喻 (Iron Cage 结论页备选) */
html[data-variant="iron-cage"] #stage {
  background-color: #171614;
  background-image:
    radial-gradient(circle at 50% 30%, rgba(60, 50, 42, 0.4) 0%, transparent 70%),
    linear-gradient(to right, rgba(255, 255, 255, 0.03) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
  background-size: 100% 100%, 80px 80px, 80px 80px;
  color: #EDE9E1;
  --text: #EDE9E1;
  --text-pure: #FFFFFF;
  --muted: #A39D92;
  --muted-dark: #C9C4BA;
  --border: #3A3630;
  --border-light: #2B2824;
  --bg-card: #201E1A;
  --surface: #272420;
}

/* 排版角色定义 */
.nt-display {
  font-family: var(--font-serif);
  font-size: var(--fs-display);
  line-height: var(--lh-tight);
  font-weight: 700;
  color: var(--text-pure);
  letter-spacing: -0.02em;
  margin: 0;
}

.nt-title {
  font-family: var(--font-serif);
  font-size: var(--fs-h1);
  line-height: var(--lh-heading);
  font-weight: 600;
  color: var(--text-pure);
  letter-spacing: -0.015em;
  margin: 0;
}

.nt-title:lang(zh),
.nt-title:lang(zh-CN) {
  font-weight: 600;
  letter-spacing: 0.02em;
}

.nt-subtitle {
  font-family: var(--font-sans);
  font-size: var(--fs-sec);
  line-height: 1.4;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--accent-ochre);
  margin: 0;
}

.nt-lead {
  font-family: var(--font-sans);
  font-size: var(--fs-lead);
  line-height: var(--lh-body);
  font-weight: 400;
  color: var(--muted-dark);
  margin: 0;
}

.nt-body {
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  line-height: var(--lh-body);
  font-weight: 400;
  color: var(--text);
  margin: 0;
}

.nt-caption {
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  line-height: 1.45;
  font-weight: 400;
  color: var(--muted);
  margin: 0;
}

/* 经典学术引言块 */
.nt-quote {
  font-family: var(--font-serif);
  font-size: 19px;
  line-height: var(--lh-relaxed);
  font-style: normal;
  color: var(--text-pure);
  border-left: 3px solid var(--accent-ochre);
  padding: 8px 0 8px 24px;
  margin: 0;
  position: relative;
}

.nt-quote em {
  font-style: italic;
  color: var(--accent-ochre);
}

.nt-quote-cite {
  display: block;
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-style: normal;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--muted);
  margin-top: 10px;
}

/* 书本/档案感卡片面板 */
.nt-card {
  box-sizing: border-box;
  background-color: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  box-shadow: var(--shadow-sm);
  padding: 24px;
}

.nt-card--elevated {
  background-color: var(--surface);
  border-color: var(--border-light);
  box-shadow: var(--shadow-md);
}

.nt-card--ochre {
  background-color: #F8F3EC;
  border-left: 4px solid var(--accent-ochre);
}

.nt-card--slate {
  background-color: #F0F3F5;
  border-left: 4px solid var(--accent-slate);
}

/* 典籍装饰分隔线与角标 */
.nt-rule {
  width: 100%;
  height: 1px;
  background-color: var(--border);
  border: none;
  margin: 16px 0;
}

.nt-rule--ornament {
  position: relative;
  height: 1px;
  background-color: var(--border);
  margin: 24px 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.nt-rule--ornament::after {
  content: "✦";
  font-size: 10px;
  color: var(--muted-light);
  background-color: var(--bg);
  padding: 0 12px;
}

/* 概念标签与徽章 */
.nt-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 600;
  letter-spacing: 0.02em;
  padding: 4px 10px;
  border-radius: 2px;
  background-color: rgba(30, 27, 24, 0.05);
  color: var(--muted-dark);
  border: 1px solid var(--border);
}

.nt-badge--ochre {
  background-color: rgba(150, 79, 36, 0.08);
  color: var(--accent-ochre);
  border-color: rgba(150, 79, 36, 0.2);
}

.nt-badge--slate {
  background-color: rgba(59, 83, 96, 0.08);
  color: var(--accent-slate);
  border-color: rgba(59, 83, 96, 0.2);
}

.nt-badge--gold {
  background-color: rgba(192, 138, 62, 0.1);
  color: #8C5F1C;
  border-color: rgba(192, 138, 62, 0.25);
}

/* 交互与控件基石：选项卡、按钮、开关 */
.nt-control-btn {
  font-family: var(--font-sans);
  font-size: var(--fs-sec);
  font-weight: 500;
  color: var(--muted-dark);
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 3px;
  padding: 8px 16px;
  cursor: pointer;
  transition: all 0.15s ease-out;
  box-sizing: border-box;
}

.nt-control-btn:hover {
  background-color: var(--surface);
  color: var(--text-pure);
  border-color: var(--muted-light);
}

.nt-control-btn[aria-pressed="true"],
.nt-control-btn.is-active {
  background-color: var(--accent-ochre);
  color: #FFFFFF;
  border-color: var(--accent-ochre);
  box-shadow: var(--shadow-sm);
}

.nt-control-btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

/* 概念连线与推演图解共享样式 (SVG 与 HTML 共用) */
.nt-diagram-line {
  stroke: var(--border-dark);
  stroke-width: 1.5;
  fill: none;
}

.nt-diagram-line--causal {
  stroke: var(--accent-ochre);
  stroke-width: 2.5;
  stroke-linecap: round;
}

.nt-diagram-line--spurious {
  stroke: var(--muted-light);
  stroke-width: 1.5;
  stroke-dasharray: 4 4;
}

.nt-diagram-node {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 4px;
  box-shadow: var(--shadow-sm);
}

/* 比较表与结构化论证表格 */
.nt-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--fs-sec);
  font-family: var(--font-sans);
}

.nt-table th {
  text-align: left;
  font-family: var(--font-sans);
  font-weight: 600;
  font-size: var(--fs-label);
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--muted-dark);
  padding: 10px 14px;
  border-bottom: 2px solid var(--border-dark);
  background: rgba(30, 27, 24, 0.02);
}

.nt-table td {
  padding: 14px;
  border-bottom: 1px solid var(--border);
  color: var(--text);
  line-height: 1.5;
}

.nt-table tr:last-child td {
  border-bottom: none;
}

/* 动效遵循 reduced-motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
